	// Guided-run library (S-1) — script copy mirrors the mobile
	// twin's ARB catalogue (guidedRunLibrary). Timing lives in code.
	"guidedRuns.easy30.title": "30-minütiger lockerer Lauf",
	"guidedRuns.easy30.subtitle": "Coach-Stimme · 30 Min · lockeres Tempo",
	"guidedRuns.easy30.description": "Ein entspannter Lauf im Plaudertempo für einen Erholungstag oder einfach zum Kopf-frei-Bekommen. Der Coach meldet sich alle fünf Minuten mit einem sanften Anstoß.",
	"guidedRuns.easy30.cue0": "Los geht’s. Starte locker — das ist dein Erholungstempo.",
	"guidedRuns.easy30.cue1": "Fünf Minuten drin. Lass die Schultern fallen. Bleib im Plaudertempo.",
	"guidedRuns.easy30.cue2": "Zehn Minuten. Schrittfrequenz-Check — schnelle Füße, leichtes Aufsetzen.",
	"guidedRuns.easy30.cue3": "Halbzeit. Du solltest dich dabei noch unterhalten können.",
	"guidedRuns.easy30.cue4": "Zwanzig Minuten. Achte auf deine Atmung — langsam durch die Nase ein, durch den Mund aus.",
	"guidedRuns.easy30.cue5": "Noch fünf Minuten. Bleib locker. Zieh nicht an.",
	"guidedRuns.easy30.cue6": "Noch eine Minute. Lockerer Abschluss.",
	"guidedRuns.easy30.cue7": "Fertig. Geh eine Minute aus. Gut gemacht.",
	"guidedRuns.tempo25.title": "25-minütiger Tempo-Aufbau",
	"guidedRuns.tempo25.subtitle": "Coach-Stimme · 25 Min · 5-15-5",
	"guidedRuns.tempo25.description": "Fünf Minuten lockeres Aufwärmen, fünfzehn Minuten im Tempo (angenehm hart), fünf Minuten Auslaufen. Die wöchentliche Standard-Tempoeinheit.",
	"guidedRuns.tempo25.cue0": "Aufwärmzeit. Fünf Minuten locker — weck die Beine auf.",
	"guidedRuns.tempo25.cue1": "Noch eine Minute Aufwärmen. Erhöhe die Schrittfrequenz.",
	"guidedRuns.tempo25.cue2": "Geh ins Tempo. Angenehm hart. Wie ein 10-km-Wettkampftempo.",
	"guidedRuns.tempo25.cue3": "Fünf Minuten im Tempo. Stark, aber kontrolliert. Halte den Rhythmus.",
	"guidedRuns.tempo25.cue4": "Zehn Minuten Tempo geschafft. Halte das Tempo.",
	"guidedRuns.tempo25.cue5": "Noch zwei Minuten im Tempo. Bleib geschmeidig.",
	"guidedRuns.tempo25.cue6": "Locker lassen. Fünf Minuten locker zum Auslaufen.",
	"guidedRuns.tempo25.cue7": "Noch zwei Minuten. Bring den Puls wieder runter.",
	"guidedRuns.tempo25.cue8": "Fertig. Geh und dehne dich. Großartige Arbeit.",
	"guidedRuns.first15.title": "Einsteiger: 15-minütiges Lauf/Geh-Training",
	"guidedRuns.first15.subtitle": "Coach-Stimme · 15 Min · Lauf/Geh-Intervalle",
	"guidedRuns.first15.description": "Neu beim Laufen? Drei Runden aus einer Minute Laufen und einer Minute Gehen, plus Aufwärmen und Auslaufen. Ein sanfter Einstieg; jeder fängt hier an.",
	"guidedRuns.first15.cue0": "Beginne mit drei Minuten zügigem Gehen zum Aufwärmen.",
	"guidedRuns.first15.cue1": "Wechsle zu einer Minute lockerem Laufen. Plaudertempo.",
	"guidedRuns.first15.cue2": "Geh eine Minute.",
	"guidedRuns.first15.cue3": "Lauf eine Minute.",
	"guidedRuns.first15.cue4": "Geh eine Minute.",
	"guidedRuns.first15.cue5": "Lauf eine Minute.",
	"guidedRuns.first15.cue6": "Geh eine Minute.",
