	"prefs.demographicsConsent": "Ich willige ein, dass Threkir mein Geschlecht, mein Geburtsdatum, meine Größe und mein Gewicht für die oben beschriebene Einstufung in Segment-Bestenlisten und für die Ernährungsziele speichert (Art. 9 Abs. 2 lit. a DSGVO).",
